import numpy as np
def read_xyz(p):
    L=open(p).read().split('\n')
    n=int(L[0]); ats=[]; P=[]
    for line in L[2:2+n]:
        t=line.split(); ats.append(t[0]); P.append([float(x) for x in t[1:4]])
    return ats,np.array(P)
a,P = read_xyz('opt1.xyz')
def d(i,j): return float(np.linalg.norm(P[i]-P[j]))
for pair,lab in [((0,1),'Co1-Co2'),((0,2),'Co1-NamL'),((0,3),'Co1-Nimine'),((0,4),'Co1-Ncarbaz'),((0,5),'Co1-NamR'),((1,6),'Co2-Nimido'),((1,27),'Co2-PL'),((1,29),'Co2-PR')]:
    print(lab, round(d(*pair),2))
cov={'H':0.31,'C':0.76,'N':0.71,'P':1.07,'Si':1.11,'Co':1.26}
vals=[]
for i in range(len(P)):
    for j in range(i+1,len(P)):
        r=float(np.linalg.norm(P[i]-P[j]))
        vals.append((r-0.85*(cov[a[i]]+cov[a[j]]),i,j,round(r,2)))
vals.sort()
print('worst contacts:', [(round(v[0],2),a[v[1]],a[v[2]],v[3]) for v in vals[:6]])
